//! Offline docs index and search behind `wj docs <query>` and the MCP `docs_search` tool.
//!
//! The index is generated by `wj agent-index` into `agent_index/docs_index.json` and embedded in the
//! binary, so lookups need no network and no repository checkout.

use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::Path;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct DocEntry {
    /// `stdlib`, `builtin`, `intrinsic`-style kinds from builtins.txt, `example`, `guide` or `error`.
    pub kind: String,
    pub name: String,
    pub module: String,
    pub signature: String,
    pub summary: String,
    /// Repository-relative file the entry came from.
    pub source: String,
    pub tags: Vec<String>,
}

const EMBEDDED: &str = include_str!("../../agent_index/docs_index.json");

pub fn embedded_index() -> Vec<DocEntry> {
    serde_json::from_str(EMBEDDED).unwrap_or_default()
}

/// Rank entries for `query` (whitespace-separated terms, case-insensitive; all terms must match somewhere).
pub fn search<'a>(entries: &'a [DocEntry], query: &str, limit: usize) -> Vec<&'a DocEntry> {
    let terms: Vec<String> = query
        .split_whitespace()
        .map(|t| t.to_lowercase())
        .collect();
    if terms.is_empty() {
        return vec![];
    }
    let mut scored: Vec<(i32, &DocEntry)> = entries
        .iter()
        .filter_map(|e| {
            let name = e.name.to_lowercase();
            let module = e.module.to_lowercase();
            let sig = e.signature.to_lowercase();
            let sum = e.summary.to_lowercase();
            let tags: Vec<String> = e.tags.iter().map(|t| t.to_lowercase()).collect();
            let mut total = 0;
            for t in &terms {
                let mut s = 0;
                if name == *t {
                    s += 10;
                } else if name.contains(t.as_str()) {
                    s += 5;
                }
                if tags.iter().any(|g| g == t) {
                    s += 4;
                } else if tags.iter().any(|g| g.contains(t.as_str())) {
                    s += 2;
                }
                if module == *t {
                    s += 3;
                }
                if sig.contains(t.as_str()) {
                    s += 2;
                }
                if sum.contains(t.as_str()) {
                    s += 1;
                }
                if s == 0 {
                    return None;
                }
                total += s;
            }
            // Guides and builtins first on ties: they are the most useful for a model.
            let kind_bonus = match e.kind.as_str() {
                "guide" => 2,
                "example" => 0,
                _ => 1,
            };
            Some((total * 10 + kind_bonus, e))
        })
        .collect();
    scored.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.name.cmp(&b.1.name)));
    scored.into_iter().take(limit).map(|(_, e)| e).collect()
}

pub fn format_entry(e: &DocEntry) -> String {
    let mut s = format!("[{}] {}", e.kind, if e.signature.is_empty() { &e.name } else { &e.signature });
    if !e.module.is_empty() {
        s.push_str(&format!("  ({})", e.module));
    }
    if !e.summary.is_empty() {
        s.push_str(&format!("\n    {}", e.summary));
    }
    if !e.source.is_empty() {
        s.push_str(&format!("\n    source: {}", e.source));
    }
    s
}

// ---------------------------------------------------------------------------------------------
// Index construction (used by `wj agent-index` and by the drift test)
// ---------------------------------------------------------------------------------------------

pub fn build_index(root: &Path) -> Result<Vec<DocEntry>> {
    let mut out = Vec::new();
    stdlib_entries(&root.join("std"), root, &mut out)?;
    builtin_entries(&root.join("agent_index/builtins.txt"), &mut out)?;
    example_entries(&root.join("examples/verified"), &mut out)?;
    guide_entries(&root.join("docs/agent"), root, &mut out)?;
    error_entries(&mut out);
    out.sort_by(|a, b| {
        (a.kind.as_str(), a.module.as_str(), a.name.as_str(), a.signature.as_str())
            .cmp(&(b.kind.as_str(), b.module.as_str(), b.name.as_str(), b.signature.as_str()))
    });
    Ok(out)
}

fn rel(path: &Path, root: &Path) -> String {
    path.strip_prefix(root).unwrap_or(path).to_string_lossy().replace('\\', "/")
}

fn wj_files(dir: &Path, acc: &mut Vec<std::path::PathBuf>) {
    if let Ok(rd) = fs::read_dir(dir) {
        for e in rd.flatten() {
            let p = e.path();
            if p.is_dir() {
                wj_files(&p, acc);
            } else if p.extension().and_then(|x| x.to_str()) == Some("wj") {
                acc.push(p);
            }
        }
    }
}

/// Top-level `fn` / `struct` / `enum` / `trait` declarations of std modules, with the `//` comment
/// block above them as the summary. Indented lines (method bodies) are skipped.
fn stdlib_entries(std_dir: &Path, root: &Path, out: &mut Vec<DocEntry>) -> Result<()> {
    let mut files = Vec::new();
    wj_files(std_dir, &mut files);
    files.sort();
    for f in files {
        let module = rel(&f, std_dir).trim_end_matches(".wj").replace('/', "::");
        let text = fs::read_to_string(&f)?;
        let mut comment: Vec<String> = Vec::new();
        for line in text.lines() {
            let t = line.trim_end();
            if let Some(c) = t.strip_prefix("//") {
                comment.push(c.trim().to_string());
                continue;
            }
            let decl = t.strip_prefix("pub ").unwrap_or(t);
            let kw = ["fn ", "struct ", "enum ", "trait "].iter().find(|k| decl.starts_with(**k));
            if let (Some(kw), false) = (kw, line.starts_with(' ') || line.starts_with('\t')) {
                let sig = decl.trim_end_matches('{').trim().to_string();
                let rest = &decl[kw.len()..];
                let name: String = rest.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
                let summary = comment
                    .iter()
                    .filter(|c| !c.is_empty() && !c.starts_with("==="))
                    .cloned()
                    .collect::<Vec<_>>()
                    .join(" ");
                out.push(DocEntry {
                    kind: "stdlib".into(),
                    name,
                    module: format!("std::{}", module),
                    signature: sig,
                    summary: summary.chars().take(160).collect(),
                    source: rel(&f, root),
                    tags: vec![kw.trim().to_string()],
                });
            }
            if !t.is_empty() {
                comment.clear();
            }
        }
    }
    Ok(())
}

fn builtin_entries(path: &Path, out: &mut Vec<DocEntry>) -> Result<()> {
    if !path.exists() {
        return Ok(());
    }
    for line in fs::read_to_string(path)?.lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.splitn(4, '|').map(|p| p.trim()).collect();
        if parts.len() < 4 {
            continue;
        }
        out.push(DocEntry {
            kind: "builtin".into(),
            name: parts[1].to_string(),
            module: parts[0].to_string(),
            signature: parts[2].to_string(),
            summary: parts[3].to_string(),
            source: "agent_index/builtins.txt".into(),
            tags: vec![parts[0].to_lowercase()],
        });
    }
    Ok(())
}

fn example_entries(dir: &Path, out: &mut Vec<DocEntry>) -> Result<()> {
    for (h, _) in super::verified::load_examples(dir)? {
        out.push(DocEntry {
            kind: "example".into(),
            name: h.name.clone(),
            module: String::new(),
            signature: String::new(),
            summary: format!("verified program; first output line: {}", h.expect.first().cloned().unwrap_or_default()),
            source: format!("examples/verified/{}.wj", h.name),
            tags: h.tags.clone(),
        });
    }
    Ok(())
}

/// Every `## heading` of the agent docs becomes a searchable entry whose summary is the first prose line.
fn guide_entries(dir: &Path, root: &Path, out: &mut Vec<DocEntry>) -> Result<()> {
    let Ok(rd) = fs::read_dir(dir) else { return Ok(()) };
    let mut files: Vec<_> = rd.flatten().map(|e| e.path()).filter(|p| p.extension().and_then(|x| x.to_str()) == Some("md")).collect();
    files.sort();
    for f in files {
        let text = fs::read_to_string(&f)?;
        let lines: Vec<&str> = text.lines().collect();
        let mut in_fence = false;
        for (i, l) in lines.iter().enumerate() {
            if l.starts_with("```") {
                in_fence = !in_fence;
            }
            if in_fence {
                continue;
            }
            if let Some(h) = l.strip_prefix("## ") {
                let summary: String = lines[i + 1..]
                    .iter()
                    .take_while(|n| !n.starts_with("## "))
                    .find(|n| !n.trim().is_empty() && !n.starts_with("```"))
                    .map(|n| n.trim().to_string())
                    .unwrap_or_default();
                out.push(DocEntry {
                    kind: "guide".into(),
                    name: h.trim().to_string(),
                    module: f.file_stem().and_then(|s| s.to_str()).unwrap_or("").to_string(),
                    signature: String::new(),
                    summary: summary.chars().take(200).collect(),
                    source: rel(&f, root),
                    tags: vec![],
                });
            }
        }
    }
    Ok(())
}

fn error_entries(out: &mut Vec<DocEntry>) {
    let registry = crate::error_codes::get_registry();
    for c in registry.all_codes() {
        out.push(DocEntry {
            kind: "error".into(),
            name: c.code.clone(),
            module: String::new(),
            signature: c.title.clone(),
            summary: c.explanation.chars().take(160).collect(),
            source: String::new(),
            tags: vec![],
        });
    }
}

/// `wj docs <query>`: print ranked results from the embedded index.
pub fn run_cli(query: &str, limit: usize, json: bool) {
    let entries = embedded_index();
    let hits = search(&entries, query, limit);
    if json {
        println!("{}", serde_json::to_string_pretty(&hits).unwrap_or_else(|_| "[]".into()));
    } else if hits.is_empty() {
        println!("no matches for `{query}`");
        let terms: Vec<&str> = query.split_whitespace().collect();
        if terms.len() > 1 {
            println!("all terms must match; results per term:");
            for t in &terms {
                println!("  `{t}`: {} entr(ies)", search(&entries, t, usize::MAX).len());
            }
            println!("drop the term with 0 entries, or search one term at a time.");
        } else {
            println!("try a shorter or different term (names, module paths and error codes are searched), or `wj docs --json <term>`.");
        }
    } else {
        for h in hits {
            println!("{}", format_entry(h));
        }
    }
}
